'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const fixtures = [
  ['', []], ['\uFEFF', []], ['\n', [['']]], ['\r\n\r\n', [[''], ['']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  [',a,,', [['', 'a', '', '']]], ['""', [['']]],
  ['"a,b","say ""hi"""\r\n', [['a,b', 'say "hi"']]],
  ['"a\r\nb\rc\nd",tail\r\n', [['a\r\nb\rc\nd', 'tail']]],
  ['a"b,c"d', [['a"b', 'c"d']]],
  ['\uFEFFx,\uFEFFy\n\uFEFFz', [['x', '\uFEFFy'], ['\uFEFFz']]],
  ['"\uD83D\uDE00",\uD83D\uDE00', [['\uD83D\uDE00', '\uD83D\uDE00']]],
  ['a;b;"c;d";', [['a', 'b', 'c;d', '']], { delimiter: ';' }],
  ['a\uD800b', [['a', 'b']], { delimiter: '\uD800' }],
];

test('grammar at every two-chunk split and one-code-unit chunks', () => {
  for (const [text, expected, options] of fixtures) {
    assert.deepEqual(parse(text, options), expected);
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser(options);
      assert.deepEqual(parser.push(''), []);
      const actual = parser.push(text.slice(0, split));
      assert.deepEqual(parser.push(''), []);
      actual.push(...parser.push(text.slice(split)), ...parser.end());
      assert.deepEqual(actual, expected, JSON.stringify([text, split]));
      assert.deepEqual(parser.end(), []);
    }
    const parser = createParser(options);
    const actual = [];
    for (let i = 0; i < text.length; i++) {
      actual.push(...parser.push(text[i]));
      assert.deepEqual(parser.push(''), []);
